<script lang="ts">
 import type {AppData} from '#lib/client/types.ts';
 import {sourceHref} from '#lib/client/source-links.ts';
  import type {Row} from '#lib/client/types.ts';
  import {display} from '#lib/client/api.ts';
  import {reportMoney,reportNumber,reportList} from '#lib/client/reports.ts';
  import Icon from '../Icon.svelte';
  let {data,aging,liquidity,currency,canWrite=false,unallocated=[]}:{data:AppData;aging:Row[];liquidity:Row[];currency?:string;canWrite?:boolean;unallocated?:Row[]}=$props();
  const groups=$derived([...new Set(aging.map(row=>(row.kind||'receivable')+':'+(row.currency||currency||'')))]);
  const bucketLabels:Record<string,string>={not_due:'Noch nicht fällig',current:'Noch nicht fällig','1_14':'1–14 Tage überfällig','15_30':'15–30 Tage überfällig','31_60':'31–60 Tage überfällig',over_60:'Mehr als 60 Tage überfällig',disputed:'Strittige Forderungen'};
</script>
{#if unallocated.length}<section class="panel mb"><header class="panel-header"><div><h2>Noch nicht zugeordnete tatsächliche Zahlungen</h2><p>Die Zahlung ist erfasst; die Zuordnung zu einem Beleg oder Geschäftsbereich ist noch offen.</p></div></header><div class="panel-body">{#each unallocated as row}<div class="inline-actions mb"><strong>{row.direction==='outgoing'?'Ausgang':'Eingang'} · {reportMoney(row.amount,row.currency)}</strong><a class="text-link" href={sourceHref(data,`/payments?${new URLSearchParams({unallocated:'true',currency:row.currency,...(row.direction?{direction:row.direction}:{})})}`)}>Zahlungen zuordnen<Icon name="arrow" size={14}/></a></div>{/each}</div></section>{/if}
<section class="panel"><header class="panel-header"><div><h2>Fälligkeiten mit Belegnachweis</h2><p>Fälligkeitstage und offene Beträge stammen aus bestätigten Belegen.</p></div></header><div class="panel-body"><p class="small mb">Strittige Forderungen werden gesondert betrachtet. Ein positiver offener Posten ist noch kein sicherer Zahlungseingang.</p>
  {#each groups as key}
    {@const rows=aging.filter(row=>(row.kind||'receivable')+':'+(row.currency||currency||'')===key)}
    {@const maximum=Math.max(0,...rows.map(row=>Math.abs(reportNumber(row.amount)||0)))}
    <div class="aging-group"><h3>{rows[0]?.kind==='payable'?'Lieferantenverbindlichkeiten':'Kundenforderungen'} · {rows[0]?.currency||currency||'Währung offen'}</h3>{#each rows as row}<div class="aging-row"><div class="aging-label"><strong>{row.label||bucketLabels[row.bucket]||'Fälligkeitsgruppe'}</strong><span>{reportNumber(row.count)===null?'Belegzahl nicht bestätigt':`${row.count} ${Number(row.count)===1?'Beleg':'Belege'}`}</span></div><div class="aging-track" aria-hidden="true"><span style={`width:${maximum&&reportNumber(row.amount)!==null?Math.abs(Number(row.amount))/maximum*100:0}%`} class:disputed={row.bucket==='disputed'}></span></div><strong class="aging-amount">{reportMoney(row.amount,row.currency||currency)}</strong>{#if row.href}<a class="text-link" href={sourceHref(data,row.href)} aria-label={`${row.label||bucketLabels[row.bucket]||'Fälligkeitsgruppe'}: Belege öffnen`}>Belege<Icon name="arrow" size={13}/></a>{:else}<span class="field-help">Drilldown nicht verfügbar</span>{/if}</div>{/each}</div>
  {/each}
  {#if !aging.length}<div class="empty-state compact"><Icon name="calendar" size={27}/><h3>Fälligkeitsgruppen noch nicht bestätigt</h3><p>Erst bestätigte offene Posten mit gültiger Fälligkeit ermöglichen eine belastbare Einordnung.</p><a class="text-link" href={sourceHref(data,'/receivables')}>Offene Forderungen prüfen<Icon name="arrow" size={14}/></a></div>{/if}
</div></section>
<section class="panel mt"><header class="panel-header"><div><h2>Liquidität nach Termin & Szenario</h2><p>Bestätigter Anfangsbestand plus erwartete Ein- und Auszahlungen.</p></div>{#if canWrite}<a class="btn small" href={sourceHref(data,'/liquidity-openings')}>Anfangsbestände prüfen<Icon name="arrow" size={14}/></a>{/if}</header><div class="panel-body"><p class="small">Ein nicht bestätigter Bankbestand bleibt offen. Szenarien zeigen Annahmen zur Fälligkeit; sie ersetzen keinen aktuellen Kontoauszug.</p></div>
  {#if liquidity.length}<div class="table-scroll"><table class="data-table"><caption class="sr-only">Erwartete Liquidität im gewählten Zeitraum nach Szenario und Währung</caption><thead><tr><th>Stichtag / Szenario</th><th class="number">Anfangsbestand</th><th class="number">Erwartete Eingänge</th><th class="number">Erwartete Ausgänge</th><th class="number">Erwarteter Bestand</th><th>Grundlage</th></tr></thead><tbody>{#each liquidity as row}<tr><th scope="row">{display(row.date||row.as_of||row.period,'date')}<span class="record-subtitle">{row.scenario_label||({base:'Nach bestätigter Fälligkeit',conservative:'Vorsichtiges Szenario',optimistic:'Früheres Zahlungsszenario'} as Record<string,string>)[row.scenario]||row.scenario||'Bestätigter Plan'}</span></th><td class="number">{reportMoney(row.opening_balance,row.currency||currency)}</td><td class="number">{reportMoney(row.expected_inflows,row.currency||currency)}</td><td class="number">{reportMoney(row.expected_outflows,row.currency||currency)}</td><td class="number">{reportMoney(row.expected_balance,row.currency||currency)}</td><td>{row.message||row.assumptions||'Noch kein vollständiger Quellennachweis'}{#if row.href}<a class="text-link mt" href={sourceHref(data,row.href)}>Grundlage öffnen<Icon name="arrow" size={13}/></a>{/if}{#if reportList(row.accounts).length||reportList(row.excluded_items).length}<details class="mt"><summary class="text-link" style="cursor:pointer">Belegte Konten & offene Annahmen</summary>{#each reportList(row.accounts) as account}<p class="field-help mt"><a class="text-link" href={sourceHref(data,`/bank-accounts/${account.bank_account_id}`)}>{account.holder||'Eigenes Konto'}</a> · {reportMoney(account.current_balance,account.currency||row.currency)}{account.opening_date?' · Eröffnung '+display(account.opening_date,'date'):''}{account.message?' · '+account.message:''}</p>{/each}{#each reportList(row.excluded_items) as item}<p class="field-help mt"><a class="text-link" href={sourceHref(data,item.href)}>Posten gesondert prüfen<Icon name="arrow" size={12}/></a> · {reportMoney(item.amount,row.currency)} · {item.due_date?display(item.due_date,'date'):'Fälligkeit fehlt'}{item.disputed?' · strittig':''}</p>{/each}</details>{/if}</td></tr>{/each}</tbody></table></div>{:else}<div class="empty-state compact"><Icon name="file" size={27}/><h3>Noch keine bestätigte Liquiditätsvorschau</h3><p>Hinterlegen Sie einen belegten Bankanfangsbestand. Unbekannte Bestände oder ungeklärte Fälligkeiten werden nicht mit null ergänzt.</p>{#if canWrite}<a class="btn" href={sourceHref(data,'/liquidity-openings')}>Bestand mit Nachweis vorbereiten</a>{/if}</div>{/if}
</section>
<style>.aging-group+.aging-group{border-top:1px solid var(--line);padding-top:26px;margin-top:26px}.aging-group h3{font-size:14px;font-weight:550;margin-bottom:24px}.aging-row{display:grid;grid-template-columns:175px minmax(40px,1fr) minmax(100px,auto) 90px;gap:18px;align-items:center;margin-top:20px}.aging-label{display:grid;gap:4px}.aging-label strong{font-size:12px;font-weight:500}.aging-label span{font-size:11px;color:var(--muted)}.aging-track{height:8px;background:#eff1eb;border-radius:3px;overflow:hidden}.aging-track span{display:block;height:100%;background:#69836a;border-radius:3px}.aging-track span.disputed{background:#aa8b5d}.aging-amount{font-size:13px;font-weight:550;text-align:right;font-variant-numeric:tabular-nums}@media(max-width:1100px){.aging-row{grid-template-columns:160px minmax(30px,1fr) minmax(100px,auto)}.aging-row>a,.aging-row>.field-help{grid-column:3}}@media(max-width:760px){.aging-row{grid-template-columns:1fr auto;gap:10px}.aging-label strong{font-size:13px}.aging-label span{font-size:12px}.aging-track{grid-column:1;grid-row:2}.aging-row>a,.aging-row>.field-help{grid-column:2;grid-row:2}.aging-amount{grid-column:2;grid-row:1;font-size:14px}.panel-header{flex-wrap:wrap}}</style>
